svg.script:
(() => {
  "use strict";

  const root = document.getElementById("skateScene");

  const $ = id => document.getElementById(id);

  /*
    Circular-pipe approximation.

    While the board is on the surface:
      theta'' = -(g / R) sin(theta)

    The ollie applies a short impulse normal to the surface. During flight,
    position follows ordinary projectile motion. On landing, only the
    velocity component tangent to the pipe is retained.
  */

  const C = {
    cx: 500,
    cy: 310,
    radius: 230
  };

  const PIXELS_PER_METRE = 92;
  const GRAVITY = 9.81 * PIXELS_PER_METRE;
  const PHYSICS_STEP = 1 / 120;

  const TRIGGER_ANGLE = 0.72;
  const TARGET_TRIGGER_SPEED = 335;
  const PUMP_DURATION = 0.42;
  const PUMP_ACCELERATION = 150;
  const GROUND_DRAG = 0.025;

  const state = {
    mode: "ground",
    theta: 0,
    omega: 455 / C.radius,

    x: C.cx,
    y: C.cy + C.radius,
    previousX: C.cx,
    previousY: C.cy + C.radius,

    vx: 0,
    vy: 0,
    airTime: 0,
    launchTheta: 0,
    boardAngle: 0,

    yaw: 0,
    yawStart: 0,
    roll: 0,

    wheelAngle: 0,
    pumpTimer: PUMP_DURATION,
    landingTimer: 0,

    trail: [],
    trailTick: 0,
    trailFade: 0,

    impactTime: 0,
    impactX: 0,
    impactY: 0,

    elapsed: 0,
    hasLaunched: false
  };

  const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
  const lerp = (a, b, t) => a + (b - a) * t;

  function setLine(id, x1, y1, x2, y2) {
    const element = $(id);
    element.setAttribute("x1", x1.toFixed(2));
    element.setAttribute("y1", y1.toFixed(2));
    element.setAttribute("x2", x2.toFixed(2));
    element.setAttribute("y2", y2.toFixed(2));
  }

  function surfaceYAt(x) {
    const dx = clamp(x - C.cx, -C.radius, C.radius);
    return C.cy + Math.sqrt(C.radius * C.radius - dx * dx);
  }

  function pumpCrouch() {
    if (state.pumpTimer <= 0) return 0;

    const phase = 1 - state.pumpTimer / PUMP_DURATION;

    if (phase < 0.42) {
      return phase / 0.42;
    }

    return 1 - (phase - 0.42) / 0.58;
  }

  function launch() {
    const theta = state.theta;
    const speed = state.omega * C.radius;

    const sin = Math.sin(theta);
    const cos = Math.cos(theta);

    /*
      Choose the pop impulse so the takeoff is slightly inward.
      This resembles turning the shoulders/board into the transition
      while extending the legs.
    */
    const desiredInwardSpeed = -18;
    const jumpSpeed = clamp(
      (speed * cos - desiredInwardSpeed) / sin,
      240,
      520
    );

    state.vx = speed * cos - jumpSpeed * sin;
    state.vy = -speed * sin - jumpSpeed * cos;

    state.x = C.cx + C.radius * sin;
    state.y = C.cy + C.radius * cos;
    state.previousX = state.x;
    state.previousY = state.y;

    state.mode = "air";
    state.airTime = 0;
    state.launchTheta = theta;
    state.boardAngle = -theta;

    state.yawStart = state.yaw;
    state.roll = 0;

    state.trail = [[state.x, state.y]];
    state.trailTick = 0;
    state.trailFade = 0;

    state.hasLaunched = true;
  }

  /*
    Find the first non-zero intersection of a line segment with the
    lower half of the circular riding surface.
  */
  function circleSegmentHit(x0, y0, x1, y1) {
    const ox = x0 - C.cx;
    const oy = y0 - C.cy;
    const dx = x1 - x0;
    const dy = y1 - y0;

    const a = dx * dx + dy * dy;
    const b = 2 * (ox * dx + oy * dy);
    const c = ox * ox + oy * oy - C.radius * C.radius;

    if (a < 1e-8) return null;

    const discriminant = b * b - 4 * a * c;
    if (discriminant < 0) return null;

    const root = Math.sqrt(discriminant);
    const candidates = [
      (-b - root) / (2 * a),
      (-b + root) / (2 * a)
    ].sort((aValue, bValue) => aValue - bValue);

    for (const u of candidates) {
      if (u <= 0.025 || u > 1) continue;

      const hitX = x0 + dx * u;
      const hitY = y0 + dy * u;

      // Only the lower semicircle is a rideable surface.
      if (hitY >= C.cy - 1) {
        return { x: hitX, y: hitY };
      }
    }

    return null;
  }

  function land(hit) {
    const theta = Math.atan2(hit.x - C.cx, hit.y - C.cy);
    const tangentX = Math.cos(theta);
    const tangentY = -Math.sin(theta);

    // Project the flight velocity onto the surface tangent.
    const tangentVelocity = state.vx * tangentX + state.vy * tangentY;

    state.x = hit.x;
    state.y = hit.y;
    state.previousX = hit.x;
    state.previousY = hit.y;

    state.theta = theta;
    state.omega = clamp((tangentVelocity * 0.94) / C.radius, -4.5, 4.5);
    state.boardAngle = -theta;

    state.mode = "ground";
    state.yaw = state.yawStart + Math.PI;
    state.roll = 0;

    state.pumpTimer = 0;
    state.landingTimer = 0.3;
    state.trailFade = 1;

    state.impactTime = 0.38;
    state.impactX = hit.x;
    state.impactY = hit.y;
  }

  function stepGround(dt) {
    const oldTheta = state.theta;

    // Gravity projected along the circular surface.
    state.omega += -(GRAVITY / C.radius) * Math.sin(state.theta) * dt;

    // A short extension pulse near the flat adds tangential work.
    if (state.pumpTimer > 0) {
      state.pumpTimer = Math.max(0, state.pumpTimer - dt);
      const phase = 1 - state.pumpTimer / PUMP_DURATION;

      if (phase > 0.42 && Math.abs(state.omega) > 0.05) {
        const extension = (phase - 0.42) / 0.58;
        const workShape = Math.sin(Math.PI * extension);

        state.omega +=
          Math.sign(state.omega) *
          PUMP_ACCELERATION *
          workShape *
          dt /
          C.radius;
      }
    }

    /*
      Light transition scrub prevents the takeoff from becoming
      unrealistically fast after repeated tricks. It represents
      controlled edge drag/carving in the steep part of the pipe.
    */
    if (state.theta > 0.42 && state.omega > 0) {
      const speed = state.omega * C.radius;
      const excess = Math.max(0, speed - TARGET_TRIGGER_SPEED);
      const deceleration = Math.min(300, excess * 2.4);

      state.omega -= deceleration * dt / C.radius;
    }

    // Rolling resistance.
    state.omega *= Math.exp(-GROUND_DRAG * dt);
    state.theta += state.omega * dt;

    // Start the compression/extension cycle at each bottom passage.
    if (
      oldTheta * state.theta < 0 &&
      state.pumpTimer <= 0 &&
      Math.abs(state.omega) > 0.1
    ) {
      state.pumpTimer = PUMP_DURATION;
    }

    // The wheels roll only while the board is on the surface.
    state.wheelAngle -= state.omega * C.radius * dt / 5.5;

    if (
      state.theta >= TRIGGER_ANGLE &&
      state.omega > 0 &&
      state.elapsed > 0.1
    ) {
      launch();
    }
  }

  function stepAir(dt) {
    state.previousX = state.x;
    state.previousY = state.y;

    state.vy += GRAVITY * dt;
    state.x += state.vx * dt;
    state.y += state.vy * dt;
    state.airTime += dt;

    const progress = clamp(state.airTime / 1.05, 0, 1);

    // A smooth body yaw and a full board rotation.
    state.yaw = state.yawStart + Math.PI * progress;
    state.roll = Math.PI * 2 * progress;

    state.trailTick++;
    if (state.trailTick % 4 === 0) {
      state.trail.push([state.x, state.y]);
      if (state.trail.length > 80) state.trail.shift();
    }

    const hit = circleSegmentHit(
      state.previousX,
      state.previousY,
      state.x,
      state.y
    );

    if (hit) {
      land(hit);
    } else if (state.airTime > 2.4) {
      // Defensive fallback for unusual numerical states.
      const dx = clamp(state.x - C.cx, -C.radius + 1, C.radius - 1);
      const theta = Math.atan2(dx, Math.sqrt(C.radius * C.radius - dx * dx));

      land({
        x: C.cx + C.radius * Math.sin(theta),
        y: C.cy + C.radius * Math.cos(theta)
      });
    }
  }

  function step(dt) {
    state.elapsed += dt;

    if (state.landingTimer > 0) {
      state.landingTimer = Math.max(0, state.landingTimer - dt);
    }

    if (state.impactTime > 0) {
      state.impactTime = Math.max(0, state.impactTime - dt);
    }

    if (state.mode === "ground") {
      if (state.trailFade > 0) {
        state.trailFade = Math.max(0, state.trailFade - dt * 0.8);
      }
      stepGround(dt);
    } else {
      stepAir(dt);
    }
  }

  function updatePose() {
    const airborne = state.mode === "air";
    const progress = airborne ? clamp(state.airTime / 1.05, 0, 1) : 0;

    let crouch = 0;

    if (airborne) {
      crouch = 0.55 + 0.18 * Math.sin(Math.PI * progress);
    } else {
      crouch = Math.max(
        pumpCrouch(),
        state.landingTimer > 0 ? state.landingTimer / 0.3 : 0
      );
    }

    const hipY = -53 + crouch * 20;
    const kneeY = -32 + crouch * 15;
    const shoulderY = -91 + crouch * 19;
    const headY = shoulderY - 24;

    const lean = airborne ? -5 * Math.sin(progress * Math.PI * 2) : 0;

    const gripAmount = airborne
      ? Math.sin(
          Math.PI * clamp((progress - 0.08) / 0.84, 0, 1)
        )
      : 0;

    // Legs remain planted on the deck while the body compresses.
    setLine("backThigh", -4 + lean * 0.2, hipY, -15, kneeY);
    setLine("backShin", -15, kneeY, -21, -14);

    setLine("frontThigh", 4 + lean * 0.2, hipY, 15, kneeY);
    setLine("frontShin", 15, kneeY, 20, -14);

    setLine("hips", -9 + lean * 0.2, hipY, 9 + lean * 0.2, hipY);
    setLine("torso", lean * 0.25, hipY, lean, shoulderY);

    // Back arm counterbalances the rotation.
    const backElbowX = -28 + lean;
    const backElbowY = shoulderY + 3;
    const backHandX = -45 + lean;
    const backHandY = shoulderY - 6;

    setLine(
      "backUpperArm",
      lean - 5,
      shoulderY + 2,
      backElbowX,
      backElbowY
    );
    setLine(
      "backForearm",
      backElbowX,
      backElbowY,
      backHandX,
      backHandY
    );
    $("backHand").setAttribute("cx", backHandX.toFixed(2));
    $("backHand").setAttribute("cy", backHandY.toFixed(2));

    // The front hand moves from a balance position to a board grab.
    const frontElbowX = lerp(28 + lean, 25, gripAmount);
    const frontElbowY = lerp(
      shoulderY + 5,
      -54 + crouch * 10,
      gripAmount
    );
    const frontHandX = lerp(43 + lean, 18, gripAmount);
    const frontHandY = lerp(shoulderY - 4, -14, gripAmount);

    setLine(
      "frontUpperArm",
      lean + 5,
      shoulderY + 2,
      frontElbowX,
      frontElbowY
    );
    setLine(
      "frontForearm",
      frontElbowX,
      frontElbowY,
      frontHandX,
      frontHandY
    );

    $("frontHand").setAttribute("cx", frontHandX.toFixed(2));
    $("frontHand").setAttribute("cy", frontHandY.toFixed(2));

    $("grip").setAttribute("cx", frontHandX.toFixed(2));
    $("grip").setAttribute("cy", frontHandY.toFixed(2));
    $("grip").setAttribute("opacity", (gripAmount * 0.9).toFixed(3));

    // Head, cap and face.
    $("head").setAttribute("cx", lean.toFixed(2));
    $("head").setAttribute("cy", headY.toFixed(2));

    $("cap").setAttribute(
      "d",
      `M${lean - 13},${headY + 1}
       C${lean - 15},${headY - 14}
       ${lean + 13},${headY - 17}
       ${lean + 13},${headY - 1}
       L${lean + 9},${headY + 2}Z`
    );

    $("brim").setAttribute(
      "d",
      `M${lean + 7},${headY - 1}
       Q${lean + 20},${headY + 1}
       ${lean + 18},${headY + 4}
       L${lean + 6},${headY + 2}Z`
    );

    $("face").setAttribute(
      "d",
      `M${lean + 7},${headY - 1}L${lean + 10},${headY + 2}`
    );
  }

  function updateTrail() {
    const points = state.trail
      .map(point => `${point[0].toFixed(1)},${point[1].toFixed(1)}`)
      .join(" ");

    $("trajectory").setAttribute("points", points);
    $("trajectory").setAttribute(
      "opacity",
      state.mode === "air"
        ? "0.45"
        : (state.trailFade * 0.35).toFixed(3)
    );
  }

  function updateImpact() {
    if (state.impactTime <= 0) {
      $("impactRing").setAttribute("opacity", "0");
      return;
    }

    const progress = 1 - state.impactTime / 0.38;

    $("impactRing").setAttribute(
      "transform",
      `translate(${state.impactX} ${state.impactY})`
    );
    $("impactRing").setAttribute("rx", (8 + progress * 42).toFixed(2));
    $("impactRing").setAttribute("ry", (3 + progress * 11).toFixed(2));
    $("impactRing").setAttribute(
      "opacity",
      ((1 - progress) * 0.58).toFixed(3)
    );
  }

  function updateTelemetry() {
    let speedPixels;
    let heightPixels = 0;

    if (state.mode === "air") {
      speedPixels = Math.hypot(state.vx, state.vy);
      heightPixels = Math.max(0, surfaceYAt(state.x) - state.y);
    } else {
      speedPixels = Math.abs(state.omega) * C.radius;
    }

    const kinetic = 0.5 * speedPixels * speedPixels;
    const potential = GRAVITY * heightPixels;
    const energy = (kinetic + potential) / PIXELS_PER_METRE;

    let mode = "ROLLING";

    if (state.mode === "air") {
      mode = "AIR - 360 FLIP + GRAB";
    } else if (!state.hasLaunched && state.elapsed < 1) {
      mode = "DROP IN";
    } else {
      const phase = state.pumpTimer > 0
        ? 1 - state.pumpTimer / PUMP_DURATION
        : 0;

      if (phase > 0.42) {
        mode = "PUMP";
      } else {
        mode = state.omega >= 0 ? "TRANSITION RIGHT" : "TRANSITION LEFT";
      }
    }

    $("modeText").textContent = mode;
    $("speedText").textContent =
      `${(speedPixels / PIXELS_PER_METRE).toFixed(1)} m/s`;
    $("heightText").textContent =
      `${(heightPixels / PIXELS_PER_METRE).toFixed(2)} m`;

    $("energyBar").setAttribute(
      "width",
      (clamp(energy / 1200, 0, 1) * 195).toFixed(2)
    );
  }

  function updateDom() {
    const airborne = state.mode === "air";
    const theta = airborne ? state.launchTheta : state.theta;
    const angle = airborne ? state.boardAngle : -theta;

    $("skater").setAttribute(
      "transform",
      `translate(${state.x.toFixed(2)} ${state.y.toFixed(2)})`
    );

    $("yawGroup").setAttribute(
      "transform",
      `scale(${Math.cos(state.yaw).toFixed(5)} 1)`
    );

    $("boardPivot").setAttribute(
      "transform",
      `rotate(${angle.toFixed(3)})`
    );

    $("human").setAttribute(
      "transform",
      `rotate(${angle.toFixed(3)})`
    );

    // A kickflip rotates the deck about its longitudinal axis.
    const flipScale = 0.18 + 0.82 * Math.abs(Math.cos(state.roll));
    $("deckFlip").setAttribute(
      "transform",
      `scale(1 ${flipScale.toFixed(4)})`
    );

    $("deckBase").setAttribute(
      "fill",
      Math.cos(state.roll) >= 0 ? "#fb6b3b" : "#2563eb"
    );

    $("deckGraphic").setAttribute(
      "opacity",
      Math.max(0, Math.cos(state.roll)).toFixed(3)
    );

    $("noseMark").setAttribute(
      "opacity",
      Math.max(0, Math.cos(state.roll)).toFixed(3)
    );

    $("wheelSpinL").setAttribute(
      "transform",
      `rotate(${state.wheelAngle.toFixed(2)})`
    );
    $("wheelSpinR").setAttribute(
      "transform",
      `rotate(${state.wheelAngle.toFixed(2)})`
    );

    updatePose();
    updateTrail();
    updateImpact();
    updateTelemetry();

    // Shadow follows either the rider or its projection onto the bowl.
    let shadowX = state.x;
    let shadowY = state.y;
    let shadowAngle = airborne ? 0 : -theta;
    let shadowOpacity = 0.25;

    if (airborne) {
      shadowY = surfaceYAt(state.x) + 2;
      const height = Math.max(0, shadowY - state.y);
      shadowOpacity = 0.27 * (1 - clamp(height / 360, 0, 0.78));
    } else {
      shadowY += 2;
    }

    $("riderShadow").setAttribute(
      "transform",
      `translate(${shadowX.toFixed(2)} ${shadowY.toFixed(2)}) ` +
      `rotate(${shadowAngle.toFixed(2)})`
    );
    $("riderShadow").setAttribute(
      "opacity",
      shadowOpacity.toFixed(3)
    );
  }

  let paused = false;
  let lastTime = performance.now();
  let accumulator = 0;

  const reducedMotion =
    window.matchMedia &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  if (reducedMotion) {
    paused = true;
    $("pauseText").textContent = "CLICK TO PLAY";
  }

  root.style.cursor = "pointer";

  root.addEventListener("click", () => {
    paused = !paused;
    $("pauseText").textContent = paused ? "CLICK TO PLAY" : "CLICK TO PAUSE";
    lastTime = performance.now();
    updateDom();
  });

  document.addEventListener("visibilitychange", () => {
    lastTime = performance.now();
    accumulator = 0;
  });

  function frame(now) {
    const frameTime = Math.min(0.05, (now - lastTime) / 1000);
    lastTime = now;

    if (!paused) {
      accumulator += frameTime;

      while (accumulator >= PHYSICS_STEP) {
        step(PHYSICS_STEP);
        accumulator -= PHYSICS_STEP;
      }

      updateDom();
    }

    requestAnimationFrame(frame);
  }

  updateDom();
  requestAnimationFrame(frame);
})();
